import os,sys,docx,email
from multiprocessing import Pool
from email import policy
root="/workspace/documents"
def conv(p):
    out="/workspace/txt/"+os.path.relpath(p,root)+".txt"
    os.makedirs(os.path.dirname(out),exist_ok=True)
    try:
        if p.endswith(".docx"):
            d=docx.Document(p); parts=[x.text for x in d.paragraphs]
            for t in d.tables:
                for r in t.rows:
                    parts.append(" | ".join(c.text for c in r.cells))
            s="\n".join(parts)
        elif p.endswith(".eml"):
            m=email.message_from_file(open(p,errors="ignore"),policy=policy.default)
            b=m.get_body(preferencelist=("plain","html"))
            s="\n".join(f"{k}: {v}" for k,v in m.items())+"\n\n"+(b.get_content() if b else "")
        elif p.endswith(".xlsx"):
            import openpyxl
            wb=openpyxl.load_workbook(p,read_only=True,data_only=True); parts=[]
            for ws in wb:
                parts.append("## "+ws.title)
                for r in ws.iter_rows(values_only=True):
                    parts.append(" | ".join("" if c is None else str(c) for c in r))
            s="\n".join(parts)
        elif p.endswith(".pptx"):
            from pptx import Presentation
            pr=Presentation(p); parts=[]
            for sl in pr.slides:
                for sh in sl.shapes:
                    if sh.has_text_frame: parts.append(sh.text_frame.text)
            s="\n".join(parts)
        open(out,"w").write(s)
    except Exception as e:
        open(out,"w").write("ERR "+str(e))
fs=[os.path.join(d,f) for d,_,fl in os.walk(root) for f in fl]
Pool(8).map(conv,fs,chunksize=20)
EOF
python3 /workspace/conv.py; find /workspace/txt -type f | wc -l; rg -l "^ERR " /workspace/txt | wc -l
